-- Embedded StreamRoute QuickApp icon.

StreamRouteIcon = StreamRouteIcon or {}
StreamRouteIcon.hex = [[]]

local ICON_STORAGE_KEY = "streamRouteIconIdV1"
local CUSTOM_ICON_ID_MIN = 1000

local function iconBytes()
  local hex = tostring(StreamRouteIcon.hex or ""):gsub("%s+", "")
  assert(#hex > 0 and #hex % 2 == 0 and hex:match("^%x+$"),
    "Embedded StreamRoute icon is invalid")

  local bytes = {}
  hex:gsub("(..)", function(pair)
    bytes[#bytes + 1] = string.char(tonumber(pair, 16))
  end)
  return table.concat(bytes)
end

local function readSelectedIcon(self)
  local selected = tonumber(self.properties and self.properties.deviceIcon)
  if api and api.get then
    local ok, device = pcall(api.get, "/devices/" .. tostring(self.id))
    if ok and type(device) == "table" and type(device.properties) == "table" then
      selected = tonumber(device.properties.deviceIcon) or selected
    end
  end
  return selected or 0
end

function QuickApp:selectStreamRouteIcon(iconId)
  local id = tonumber(iconId)
  if not id or id < CUSTOM_ICON_ID_MIN then return false, "invalid icon id" end

  local ok, errorMessage = pcall(api.put, "/devices/" .. tostring(self.id), {
    properties = { deviceIcon = id },
  })
  if not ok then return false, tostring(errorMessage) end

  if readSelectedIcon(self) ~= id then
    return false, "HC3 rejected icon id " .. tostring(id)
  end

  self.properties = self.properties or {}
  self.properties.deviceIcon = id
  self:internalStorageSet(ICON_STORAGE_KEY, tostring(id))
  return true, id
end

function QuickApp:ensureStreamRouteIcon()
  local selected = readSelectedIcon(self)
  if selected >= CUSTOM_ICON_ID_MIN then
    self:internalStorageSet(ICON_STORAGE_KEY, tostring(selected))
    return
  end

  local stored = tonumber(self:internalStorageGet(ICON_STORAGE_KEY) or 0) or 0
  if stored >= CUSTOM_ICON_ID_MIN then
    local restored = self:selectStreamRouteIcon(stored)
    if restored then return end
  end

  if type(self.uploadIconFiles) ~= "function" or type(self.deviceIconTypeMapping) ~= "table" then
    self:warning("HC3 icon upload API is unavailable")
    return
  end

  local mapping = self.deviceIconTypeMapping[self.type]
  if type(mapping) ~= "table" or type(mapping.fileNames) ~= "table"
      or #mapping.fileNames ~= 1 then
    self:warning("Unexpected HC3 icon mapping for " .. tostring(self.type))
    return
  end

  self:uploadIconFiles({
    files = { iconBytes() },
    fileNames = mapping.fileNames,
    deviceType = self.type,
  }, {}, function(id)
    local installed, installError = self:selectStreamRouteIcon(id)
    if installed then
      self:debug("StreamRoute icon installed: deviceIcon=" .. tostring(id))
    else
      self:warning("StreamRoute icon could not be selected: " .. tostring(installError))
    end
  end, function(uploadError)
    self:warning("StreamRoute icon upload failed: " .. tostring(uploadError))
  end)
end
